mapper.select:
select ID, USER_ID, AGENT_ID, STATUS, PURPOSE, CREATED_AT, EXPIRED_AT
from AGENT_TASK where USER_ID = #{user_id}

    and AGENT_ID = #{agent_id}

order by ID

mapper.update:
update AGENT_TASK set PURPOSE = #{task.purpose}, EXPIRED_AT = #{task.expired_at}
where ID = #{task.id} and USER_ID = #{user_id}
  and STATUS = 'RUNNING' and EXPIRED_AT > CURRENT_TIMESTAMP

update AGENT_TASK set STATUS = #{status}
where ID = #{id} and USER_ID = #{user_id}
  and STATUS = 'RUNNING' and EXPIRED_AT > CURRENT_TIMESTAMP
